import json, math

qs80 = json.load(open('all.json'))
qs20 = json.load(open('dev3.json'))['questions']

def by_variant(samples):
    d={}
    for s in samples: d.setdefault(s['variant'],[]).append(s)
    return d

def score_weighted_scores(samples, temp):
    sums={}
    for s in samples:
        sums[s['answer']]=sums.get(s['answer'],0)+math.exp(s['score']/temp)
    return sums

def confidence_margin(sums):
    if not sums: return 0.0
    vals=sorted(sums.values(), reverse=True)
    total=sum(vals)
    if len(vals)==1: return 1.0
    return (vals[0]-vals[1])/total

def simulate(qs, phase1_n, cap, temp, budget_per_q=6.0):
    n=len(qs)
    qmap={q['id']: by_variant(q['samples']) for q in qs}
    alloc={q['id']: [] for q in qs}
    vidx={q['id']: {v:0 for v in range(5)} for q in qs}
    total_budget = int(round(budget_per_q*n))
    used=0
    # phase1: round robin variant order starting at 0
    for q in qs:
        qid=q['id']
        for k in range(phase1_n):
            v = k % 5
            lst = qmap[qid].get(v, [])
            i = vidx[qid][v]
            if i < len(lst):
                alloc[qid].append(lst[i]); vidx[qid][v]+=1; used+=1
    remaining = total_budget - used
    next_v = {q['id']: phase1_n % 5 for q in qs}  # continue cycling variant
    def total_taken(qid): return len(alloc[qid])
    while remaining > 0:
        worst=None; worst_conf=2.0
        for q in qs:
            qid=q['id']
            if total_taken(qid) >= cap: continue
            v = next_v[qid]
            lst = qmap[qid].get(v, [])
            i = vidx[qid][v]
            if i >= len(lst):
                # try to advance variant pointer virtually? skip if unavailable in sim data
                continue
            sums = score_weighted_scores(alloc[qid], temp)
            c = confidence_margin(sums)
            if c < worst_conf:
                worst_conf = c; worst = (qid, v)
        if worst is None: break
        qid, v = worst
        lst = qmap[qid][v]
        i = vidx[qid][v]
        alloc[qid].append(lst[i]); vidx[qid][v]+=1
        next_v[qid] = (v+1) % 5
        remaining -= 1
    acc=0
    for q in qs:
        qid=q['id']
        sums = score_weighted_scores(alloc[qid], temp)
        pred = max(sums.items(), key=lambda x:x[1])[0]
        if pred == q['correct_answer']: acc+=1
    return acc/n, remaining

results=[]
for phase1_n in [2,3,4,5]:
    for cap in [6,8,10,12,15]:
        for temp in [0.5,0.7,1.0]:
            acc80, rem80 = simulate(qs80, phase1_n, cap, temp, 6.0)
            acc20, rem20 = simulate(qs20, phase1_n, min(cap,40), temp, 6.0)
            results.append((phase1_n, cap, temp, acc80, acc20, rem80, rem20))

results.sort(key=lambda r: -(r[3]*80+r[4]*20))
for r in results[:20]:
    print(r)
